def key(s):
    s = s.lower().replace("ß", "ss")
    return "".join(c for c in unicodedata.normalize("NFD", s) if not unicodedata.combining(c))

# Sonstiges in eigene Abteilungen aufteilen
_s = C.pop("Sonstiges")
def _cut(frm, to=None):
    i = _s.index(frm); j = _s.index(to) if to else len(_s)
    return _s[i:j]
C["Kleidung & Textilien"] = _cut("Socken", "Einkaufstasche")
C["Baumarkt & Werkzeug"] = _cut("Schrauben", "Blumenerde")
C["Garten & Pflanzen"] = _cut("Blumenerde", "Socken")
C["Büro & Schule"] = _cut("Kugelschreiber", "Schrauben")
C["Sonstiges"] = _cut("Einkaufstasche")
import add1, add2, add3, add4, add5
for _m in (add1, add2, add3, add4, add5):
    for cat, txt in _m.A.items():
        C[cat] += L(txt)
