# Bereinigung nach der Durchsicht: doppelt geführte oder falsch einsortierte Artikel fallen weg
# (Milchschnitte steht im Kühlregal, Medjool-Datteln beim Obst als „Datteln Medjool“, Helva heißt hier Halva).
DROP = {"Milchschnitten", "Medjool-Datteln", "Helva"}
SYN += L("Helva=Halva;Medjool-Datteln=Datteln Medjool;Milchschnitten=Milchschnitte")
for _c in C: C[_c] = [x for x in C[_c] if x not in DROP]
seen, out, dups = {}, {k: [] for k in C}, []
for cat, items in C.items():
    for it in items:
        assert "|" not in it and "*" not in it and "=" not in it, it
        k = key(it)
        if k in seen: dups.append(it); continue
        seen[k] = it; out[cat].append(it)
total = sum(len(v) for v in out.values())
miss = [s_ for s_ in STAPLE if key(s_) not in seen]
syn, bad = [], []
for pair in SYN:
    a_, b_ = pair.split("=")
    if key(b_) not in seen: bad.append(pair); continue
    if key(a_) in seen: continue          # steht schon als eigener Artikel im Katalog
    syn.append(a_ + "=" + seen[key(b_)])
nbrand = sum(len(L(v)) for v in BR.values())
print("total", total, "marken", nbrand, "synonyme", len(syn), "dups", dups, "staple fehlt", miss, "syn fehlt", bad, file=sys.stderr)
for k, v in out.items(): print(f"  {len(v):4d} {k}", file=sys.stderr)
assert not miss and not bad
st = {key(s_) for s_ in STAPLE}
data = [[k, "|".join(i + ("*" if key(i) in st else "") for i in v)] for k, v in out.items()]
open(sys.argv[1], "w", encoding="utf-8").write(
    "/* Erzeugt von src/gen.py - nicht von Hand bearbeiten. */\n"
    "var DATA = " + json.dumps(data, ensure_ascii=False, separators=(",", ":")) + ";\n"
    "var SYNRAW = " + json.dumps("|".join(syn), ensure_ascii=False) + ";\n")
